 * System scheduler with dependency ordering.
 *
 * Systems declare `before` / `after` constraints by name. The scheduler
 * topologically sorts them, using declaration order as the stable
 * tie-break among systems whose constraints are all satisfied.
 */

export interface System {
  /** Unique system name. */
  name: string;
  /** Names of systems that must run *after* this one (this runs first). */
  before?: readonly string[];
  /** Names of systems that must run *before* this one (those run first). */
  after?: readonly string[];
}

/** Thrown when the declared constraints contain a cycle. */
export class CyclicDependencyError extends Error {
  /** The system names forming the cycle, in cycle order. */
  readonly cycle: string[];

  constructor(cycle: string[]) {
    super(
      `Cyclic dependency detected among systems: ${cycle.join(" -> ")} -> ${cycle[0]}. ` +
        `Adjust the before/after constraints to break the cycle.`
    );
    this.name = "CyclicDependencyError";
    this.cycle = cycle;
  }
}

/**
 * Order systems so every `before`/`after` constraint is respected.
 * Ties are broken by declaration order (stable).
 *
 * @throws {Error} if a constraint references an unknown system, a name is duplicated,
 *                 or the constraints are cyclic.
 */
export function scheduleSystems(systems: readonly System[]): System[] {
  const indexOf = new Map<string, number>();
  for (const [i, sys] of systems.entries()) {
    if (indexOf.has(sys.name)) {
      throw new Error(`Duplicate system name: "${sys.name}"`);
    }
    indexOf.set(sys.name, i);
  }

  for (const sys of systems) {
    for (const ref of [...(sys.before ?? []), ...(sys.after ?? [])]) {
      if (!indexOf.has(ref)) {
        throw new Error(
          `System "${sys.name}" references unknown system "${ref}" in its constraints`
        );
      }
    }
  }

  // Edge u -> v means "u must come before v".
  const edges = new Map<string, Set<string>>();
  // indegree[v] = number of systems that must precede v.
  const indegree = new Map<string, number>();
  for (const sys of systems) {
    if (!edges.has(sys.name)) edges.set(sys.name, new Set());
    indegree.set(sys.name, 0);
  }

  const addEdge = (from: string, to: string) => {
    if (!edges.get(from)!.has(to)) {
      edges.get(from)!.add(to);
      indegree.set(to, indegree.get(to)! + 1);
    }
  };

  for (const sys of systems) {
    for (const next of sys.before ?? []) addEdge(sys.name, next);
    for (const prev of sys.after ?? []) addEdge(prev, sys.name);
  }

  // Kahn's algorithm; pick the ready node with the smallest declaration index.
  const ready: string[] = [];
  for (const sys of systems) {
    if (indegree.get(sys.name) === 0) ready.push(sys.name);
  }

  const ordered: string[] = [];
  while (ready.length > 0) {
    let bestIdx = 0;
    for (let i = 1; i < ready.length; i++) {
      if (indexOf.get(ready[i])! < indexOf.get(ready[bestIdx])!) bestIdx = i;
    }
    const current = ready.splice(bestIdx, 1)[0];
    ordered.push(current);
    for (const next of edges.get(current)!) {
      indegree.set(next, indegree.get(next)! - 1);
      if (indegree.get(next) === 0) ready.push(next);
    }
  }

  if (ordered.length !== systems.length) {
    throw new CyclicDependencyError(findCycle(systems, indexOf));
  }

  return ordered.map((name) => systems[indexOf.get(name)!]);
}

/**
 * Extract one concrete cycle from the remaining unscheduled nodes
 * by walking predecessor edges until a node repeats.
 */
function findCycle(systems: readonly System[], indexOf: Map<string, number>): string[] {
  const remaining = new Set(systems.map((s) => s.name));
  const preds = new Map<string, Set<string>>();
  for (const name of remaining) preds.set(name, new Set());
  for (const sys of systems) {
    for (const next of sys.before ?? []) preds.get(next)!.add(sys.name);
    for (const prev of sys.after ?? []) preds.get(prev)!.add(sys.name);
  }

  const start = [...remaining][0];
  const path: string[] = [start];
  const seen = new Map<string, number>([[start, 0]]);

  let current = start;
  for (;;) {
    const pred = [...preds.get(current)!].find((p) => remaining.has(p))!;
    if (seen.has(pred)) {
      return path.slice(seen.get(pred)!);
    }
    seen.set(pred, path.length);
    path.push(pred);
    current = pred;
  }
}
