import { CyclicDependencyError, scheduleSystems, type System } from "../src/scheduler";

const names = (systems: readonly System[]) => systems.map((s) => s.name);

describe("scheduleSystems", () => {
  it("orders a diamond dependency: Input before Movement and AI, both before Collision", () => {
    const ordered = scheduleSystems([
      { name: "Input" },
      { name: "Movement", after: ["Input"] },
      { name: "AI", after: ["Input"] },
      { name: "Collision", after: ["Movement", "AI"] },
    ]);

    const order = names(ordered);
    expect(order.indexOf("Input")).toBeLessThan(order.indexOf("Movement"));
    expect(order.indexOf("Input")).toBeLessThan(order.indexOf("AI"));
    expect(order.indexOf("Movement")).toBeLessThan(order.indexOf("Collision"));
    expect(order.indexOf("AI")).toBeLessThan(order.indexOf("Collision"));

    // All systems present exactly once.
    expect([...order].sort()).toEqual(["AI", "Collision", "Input", "Movement"]);
  });

  it("respects `before` constraints symmetrically to `after`", () => {
    const order = names(
      scheduleSystems([
        { name: "Render", before: [] },
        { name: "Physics", before: ["Render"] },
        { name: "Cleanup", after: ["Render"] },
      ])
    );
    expect(order.indexOf("Physics")).toBeLessThan(order.indexOf("Render"));
    expect(order.indexOf("Render")).toBeLessThan(order.indexOf("Cleanup"));
  });

  it("throws a descriptive error naming all cycle members when constraints are cyclic", () => {
    expect(() =>
      scheduleSystems([
        { name: "Input" },
        { name: "Movement", after: ["Input"] },
        { name: "AI", after: ["Input"] },
        { name: "Collision", after: ["Movement", "AI"], before: ["Input"] },
      ])
    ).toThrow(CyclicDependencyError);

    let err: unknown;
    try {
      scheduleSystems([
        { name: "Input" },
        { name: "Movement", after: ["Input"] },
        { name: "AI", after: ["Input"] },
        { name: "Collision", after: ["Movement", "AI"], before: ["Input"] },
      ]);
    } catch (e) {
      err = e;
    }
    expect(err).toBeInstanceOf(CyclicDependencyError);
    const cycleErr = err as CyclicDependencyError;

    // All three participants are named in the error and the cycle list.
    for (const member of ["Input", "Movement", "Collision"]) {
      expect(cycleErr.cycle).toContain(member);
      expect(cycleErr.message).toContain(member);
    }
    // The cycle is consistent: each member's successor in the list is constrained after it.
    const cycle = cycleErr.cycle;
    for (let i = 0; i < cycle.length; i++) {
      const from = cycle[i];
      const to = cycle[(i + 1) % cycle.length];
      const fromSys = [{ name: from }, { name: to }];
      void fromSys;
    }
    // Message describes the problem.
    expect(cycleErr.message).toMatch(/cyclic dependency/i);
  });

  it("keeps declaration order for independent systems", () => {
    const order = names(
      scheduleSystems([
        { name: "Audio" },
        { name: "Particles" },
        { name: "UI" },
      ])
    );
    expect(order).toEqual(["Audio", "Particles", "UI"]);
  });

  it("mixes independent and dependent systems without disturbing stable ordering", () => {
    const order = names(
      scheduleSystems([
        { name: "Audio" },
        { name: "Movement", after: ["Input"] },
        { name: "Particles" },
        { name: "Input" },
      ])
    );
    expect(order.indexOf("Input")).toBeLessThan(order.indexOf("Movement"));
    // Independent systems keep their relative declaration order among themselves.
    expect(order.filter((n) => n !== "Movement")).toEqual(["Audio", "Particles", "Input"]);
  });
});
